-- FILE: 20261022160000_char.sql
-- Necromancer T2e legacy cleanup marker.  Characters that still hold the
-- trainer-taught armor passives are marked; the module removes them with
-- Player::RemoveSpell (OnForgotSpell skill/gear cleanup) and grants one
-- free talent reset.  Generated by tools/generate_talent_polish_t2e.py;
-- re-runnable.

-- 1) mark the pre-T1 characters (module reads variable type 1001)
INSERT IGNORE INTO `character_variables` (`lowGuid`, `variableType`, `value`)
SELECT DISTINCT cs.guid, 1001, '1'
FROM `character_spell` cs
JOIN `characters` c ON c.guid = cs.guid
WHERE c.class = 10 AND cs.spell IN (61090, 61091, 61092);

-- 2) grant the free talent reset up front; ResetTalents will consume it
INSERT INTO `character_variables` (`lowGuid`, `variableType`, `value`)
SELECT DISTINCT cs.guid, 4, '1'
FROM `character_spell` cs
JOIN `characters` c ON c.guid = cs.guid
WHERE c.class = 10 AND cs.spell IN (61090, 61091, 61092)
ON DUPLICATE KEY UPDATE `value` = IF(CAST(`value` AS UNSIGNED) < 1, '1', `value`);

-- 3) stale action-bar and dual-spec copies of the stripped passives
DELETE csd FROM `character_spell_dual_spec` csd
JOIN `character_variables` v ON v.lowGuid = csd.guid AND v.variableType = 1001
WHERE csd.spell IN (61090, 61091, 61092);

DELETE ca FROM `character_action` ca
JOIN `character_variables` v ON v.lowGuid = ca.guid AND v.variableType = 1001
WHERE ca.type = 0 AND ca.action IN (61090, 61091, 61092);
